672	template <OptId Opt>
673	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
674	fused_decoder_megakernel_tc(PersistentContext ctx,
675	                            float* __restrict__ params,
676	                            DecoderTokenCtx tok,
677	                            float* __restrict__ grad,
678	                            float lr, int step, FusedOptState st) {
679	#if SG_DEC_TC_DYNAMIC_SMEM
680	    // DEEP-RING path: DecTcSmem is allocated from DYNAMIC smem (sized at launch to
681	    // exactly sizeof(DecTcSmem), opt-in via cudaFuncAttributeMaxDynamicSharedMem-
682	    // orySize) so the deeper fwd/dX ring can exceed the 48 KB STATIC __shared__
683	    // cap. The extern __shared__ base is 16 B-aligned on sm_90 and DecTcSmem's
684	    // alignment is 16 B (static_assert above), so the reinterpret_cast is
685	    // well-defined; the placed object has the IDENTICAL layout/footprint as the
686	    // static path — this is purely WHERE it lives (dynamic vs static smem), not a
687	    // math/layout/access change (parity by construction).
688	    extern __shared__ char sg_dectc_pool[];
689	    DecTcSmem& sm = *reinterpret_cast<DecTcSmem*>(sg_dectc_pool);
690	#else
691	    __shared__ DecTcSmem sm;
692	#endif
693	    GridBarrier bar = ctx.barrier();
694	    // SAM-coupled cells run the tile fwd+bwd TWICE (P1 + P2.4); route BOTH their
695	    // passes through the out-of-line shims (one shared frame, campaign C2). The
696	    // single-pass cells keep the inline bodies -- byte-identical allocation.
697	    constexpr bool kSamCoupled = (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
698	                                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2);
699	    const int cta = blockIdx.x;
700	    const int nCTA = (int)ctx.n_ctas;
701	    const int B = tok.B;
702	    const int T = B * dec::kSeq;
703	
704	    // Workspace partition.
705	    float* ws = tok.workspace;
706	    const int64_t acts_f = dec_tc_acts_floats(T, B);
707	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
708	    float* scratch_base = ws + acts_f;
709	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
710	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
711	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
712	    float* loss_out   = loss_part + nCTA;
713	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
714	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
715	    float* dw_part    = loss_out + 1;
716	    const int kDwG    = dectc::kDecDwSplitK;
717	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
718	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
719	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
720	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
721	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
722	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
723	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
724	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
725	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
726	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
727	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Muon scratch (term order
728	    // matches dec_tc_workspace_floats — carving it LAST keeps every prior region's
729	    // offset unchanged, so the already-green cells are byte-identical). Layout:
730	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
731	    float* sam_backup = muon_base + dec_tc_muon_floats(nCTA);
732	    float* sam_grad   = sam_backup + kDecTotalElems;
733	    // SuperGrok2 meta-net per-CTA scratch, carved AFTER the LookSAM sam_grad (term
734	    // order matches dec_tc_workspace_floats — carving it LAST keeps every prior
735	    // region's offset unchanged, so the already-green cells are byte-identical).
736	    // Each CTA owns dec_sg2_ws_stride_floats() (row_off64 staging + meta-net scratch).
737	    // ALIGN to 8 bytes (even float offset): the per-CTA slice fronts an int64
738	    // row_off64 staging array; kDecTotalElems is odd so sam_grad+total lands on an
739	    // odd float offset (4-byte) → an int64 read there is a misaligned address. Round
740	    // up to the next even float. The carve term dec_tc_sg2_floats reserves the stride
741	    // per CTA; the +1 alignment slack fits within the acts/scratch headroom (the
742	    // workspace is over-sized) and dec_sg2_ws_stride_floats() is even, so every CTA
743	    // base stays 8-byte aligned. Unused unless Opt==SuperGrok2.
744	    float* sg2_ws_base = sam_grad + kDecTotalElems;
745	    if (((uintptr_t)sg2_ws_base & 0x7) != 0) sg2_ws_base += 1;   // → 8-byte aligned
746	    (void)sg2_ws_base;   // referenced only by the SuperGrok2 P3-SG2 phase
747	    // Embedding token-list scratch (counting-sort row_start[V+1] + perm[T]), carved
748	    // AFTER the SG2 region (term order matches dec_tc_workspace_floats — carving it
749	    // LAST keeps every prior region's offset unchanged → the green cells' non-embed
750	    // regions are byte-identical). int32 views over the float tail; 8-byte aligned so
751	    // the (future) widening to int is safe. Built in the P1 window (cta 0), consumed
752	    // in P2 — fenced by the already-present B1 barrier (no new barrier).
753	#if SG_DEC_BENCH_LAYOUT
754	    // Bench (adamw-only): the four staged-opt regions are gated to 0, so embed_ws is
755	    // the staged-opt block START (== opt_reduce) plus the aggregate (== 0 here). We
756	    // derive it from the SAME dec_tc_staged_opt_floats aggregate the host carve
757	    // (dec_tc_workspace_floats) uses, so the host size and this offset are provably the
758	    // identical expression at bench width — no reliance on the (collapsed) sg2_ws_base
759	    // chain. (opt_reduce == dw_part + dec_tc_dw_part_floats(); see its carve above.)
760	    float* wbf_f = opt_reduce + dec_tc_staged_opt_floats(nCTA);
761	    // 16B-align the bf16 cache base: the cp.async RING streams it in 16-byte
762	    // chunks (gmem source alignment requirement). Bump <= 3 floats, covered by
763	    // dec_tc_workspace_floats' slack term; deterministic (the workspace base is
764	    // >=256B-aligned, so the bump depends only on the carve offsets).
765	    while (((uintptr_t)wbf_f & 0xF) != 0) wbf_f += 1;
766	    float* embed_ws = wbf_f + dectc::dec_wbf_floats();
767	#else
768	    // Production: carve AFTER the (full-size) SG2 region via the existing chain
769	    // (the sg2_ws_base align bump + the dec_tc_sg2_floats stride are load-bearing
770	    // for the SG2 int64 row_off64 reads). The bf16 weight pre-stage cache (C1)
771	    // is interposed here; embed lists stay carve-LAST.
772	    float* wbf_f = sg2_ws_base + dec_tc_sg2_floats(nCTA);
773	    // 16B-align the bf16 cache base for the cp.async RING (see the bench-branch
774	    // note; bump <= 3 floats, covered by dec_tc_workspace_floats' slack term).
775	    while (((uintptr_t)wbf_f & 0xF) != 0) wbf_f += 1;
776	    float* embed_ws = wbf_f + dectc::dec_wbf_floats();
777	#endif
778	    if (((uintptr_t)embed_ws & 0x7) != 0) embed_ws += 1;         // → 8-byte aligned
779	    int* embed_row_start = reinterpret_cast<int*>(embed_ws);     // [V+1]
780	    int* embed_perm      = embed_row_start + (dec::kVocab + 1);  // [T]
781	    // CONTIGUOUS-TRANSPOSE dW scratch (SG_TUNED_DEC_DW_STAGE=1), carved AFTER the
782	    // embed lists (term order matches dec_tc_workspace_floats — carve-LAST keeps
783	    // every prior region's offset unchanged). #if-guarded (not a runtime ternary)
784	    // so the scalar default emits ZERO extra carve code → the kernel's register
785	    // allocation + PTX are BYTE-IDENTICAL to every shipped build (PTX-verified).
786	    // 16B-align the base: the cp.async ring streams it in 16-byte chunks (gmem
787	    // source alignment). Each transposed ROW is K-contiguous and K is a multiple
788	    // of kWgmmaAtomK=16 (⇒ 8 bf16 = 16B), so once the base is 16B-aligned every
789	    // chunk16 half-offset (mn·8 / N·8 / kbase) is too. Bump ≤ 7 floats (covered
790	    // by dec_tc_workspace_floats' +8 active-only slack term).
791	#if SG_TUNED_DEC_DW_STAGE
792	    float* dwt_f = reinterpret_cast<float*>(embed_perm + (int64_t)T);
793	    while (((uintptr_t)dwt_f & 0xF) != 0) dwt_f += 1;
794	    __nv_bfloat16* dwt_base = dectc::kDecDwTransposeActive
795	        ? reinterpret_cast<__nv_bfloat16*>(dwt_f) : nullptr;
796	#endif
797	
798	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
799	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
800	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
801	
802	    DecWeights w = dec_bind(params);
803	    // bf16 weight pre-stage cache (C1): bound over its workspace carve; FILLED in
804	    // P0 below (fenced by B0 before any P1 GEMM stages from it).
805	    __nv_bfloat16* wbf_cache = reinterpret_cast<__nv_bfloat16*>(wbf_f);
806	    dectc::DecWBf wb = dectc::dec_wbf_bind(wbf_cache);
807	
808	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
809	    //    written-once → no pre-zero). ──
810	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
811	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
812	    // C1: fill the bf16 weight cache (grid-strided, element-owned, deterministic);
813	    // B0 fences it before any P1 GEMM stages from it.
814	    dectc::dectc_wbf_convert(params, wbf_cache, cta, nCTA);
815	#ifdef SG_DEC_PROFILE
816	    unsigned long long _b0a = (threadIdx.x == 0) ? clock64() : 0;
817	#endif
818	    bar.sync();   // B0
819	#ifdef SG_DEC_PROFILE
820	    if (threadIdx.x == 0) { unsigned long long _b0b = clock64(); atomicMax(&g_dec_prof_max[7], _b0b - _b0a); }
821	#endif
822	
823	    // ── Build the embedding token lists (counting sort over tok_ids) ONCE on cta 0,
824	    //    HERE in the P1 window so it overlaps the other CTAs' fwd/bwd and the
825	    //    already-present B1 barrier fences it before the P2 consume — NO new barrier.
826	    //    cta 0 then joins P1. The build is O(T), parallel over its worker lanes, so
827	    //    it measures ~0.3 ms (≪ P1) — far below the embed-consume time it unlocks. ──
828	    if (cta == 0)
829	        dectc::dectc_embed_build_lists(tok.tokens, T, embed_row_start, embed_perm);
830	
831	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
832	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
833	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
834	    const int nrows_tile = dectc::kTileM;
835	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
836	    float nll_acc = 0.0f;
837	#ifdef SG_DEC_PROFILE
838	    unsigned long long prof_fwd = 0, prof_bwd = 0;
839	#endif
840	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
841	        const int g0 = ti * nrows_tile;
842	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
843	#ifdef SG_DEC_PROFILE
844	        __syncthreads(); unsigned long long _c0 = clock64();
845	#endif
846	        float nll;
847	        if constexpr (kSamCoupled)
848	            nll = dectc::dectc_forward_tile_outlined(w, wb, g0, nrows, acts, sc, tok.tokens,
849	                                                     tok.targets, sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
850	        else
851	            nll = dectc::dectc_forward_tile(w, wb, g0, nrows, acts, sc, tok.tokens, tok.targets,
852	                                            sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
853	#ifdef SG_DEC_PROFILE
854	        __syncthreads(); unsigned long long _c1 = clock64();
855	#endif
856	        if constexpr (kSamCoupled)
857	            dectc::dectc_backward_tile_outlined(w, wb, g0, nrows, B, acts, sc, tok.targets,
