175	// scalar_train_step: the SAME (decoder × AdamW) cell run through the SCALAR
176	// default launcher (launch_fused_decoder_megakernel<AdamW>, which lives OUTSIDE
177	// the wgmma guard at fused_decoder_megakernel.cuh — so this wgmma-token TU
178	// can still call it). This exists ONLY so the step-time gate can time the live
179	// scalar path and the TC path BACK-TO-BACK in one process / one contention
180	// regime → an honest scalar:TC ratio. The scalar path uses its OWN workspace
181	// layout (nCTA*total grad partials + nCTA loss slots + 1 reduced loss), sized
182	// for nCTA = #SMs (the scalar launcher pins one CTA per SM, no cap). It is NOT
183	// the shipped invocation (that is dispatch.cpp via mega_decoder_real_adamw.cu);
184	// it is a measurement mirror. Returns {loss, reduced grad} like tc_train_step.
185	//
186	// GATED by SG_DEC_SCALAR_MEGAKERNEL: the legacy fp32 scalar megakernel does not
187	// fit smem at scaled SG_DEC_D (see the flag note in fused_decoder_megakernel.cuh).
188	// When OFF, this back-to-back timing mirror is compiled out (its only purpose is
189	// the scalar:TC ratio, which is moot when the scalar path is unavailable); the TC
190	// gates (tc_train_step) are unaffected.
191	#if SG_DEC_SCALAR_MEGAKERNEL
192	static std::vector<torch::Tensor> scalar_train_step(
193	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
194	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
195	        double weight_decay, double bc1, double bc2, int64_t step) {
196	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
197	    TORCH_CHECK(params.numel() == kDecTotalElems, "params must be the flat decoder blob (", kDecTotalElems, ")");
198	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
199	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
200	    const int B = (int)targets.numel();

980	    //    deterministic BY CONSTRUCTION. Guarded so every other opt's path is
981	    //    byte-identical (no extra barrier / work). On a NON-SAM step (looksam_sam==0)
982	    //    this whole block is skipped — st.sam_dir already holds the cached direction.
983	    //
984	    //    SuperGrok11/15 SHARE this exact SAM 2nd-backward machinery (INTEGRATION-
985	    //    OPTSTAGES §4/§5): the perturb→2nd in-kernel fwd+bwd→restore pipeline is
986	    //    IDENTICAL; only the elementwise WRITE in step (d) differs — LookSAM writes
987	    //    st.sam_dir[i] = g_sam − g, SG11/15 write st.sharpness[i] = (g_sam − g)²
988	    //    (supergrok11_sm90.cuh:246 / supergrok15_sm90.cuh:315). sharpness is then the
989	    //    2nd MLP input the P2.45 meta-net mu precompute reads. The SAM-step gate is the
990	    //    SAME st.looksam_sam host scalar (the SG sam_step cadence); on a non-SAM step
991	    //    the cached sharpness is reused verbatim. SG reuses st.rho as the perturbation
992	    //    radius (its own sam_rho), identical reduction/perturb math.
993	    if constexpr (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
994	                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2) {
995	        if (st.looksam_sam != 0.0f) {
996	            // (a) GLOBAL ‖g‖ over the reduced grad, deterministic (reuse the loss
997	            //     workspace as P2.5 does: loss_part[nCTA] = per-CTA Σg², loss_out[1]
998	            //     broadcasts rho_over_norm). The reduced loss is already in
999	            //     *tok.loss_out (host state), so this is free scratch.
1000	            float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
1001	            float* ron_bc  = loss_out;           // [1] broadcast rho_over_norm
1002	            const int64_t total = kDecTotalElems;
1003	            {
1004	                const int64_t base = total / nCTA, rem = total % nCTA;
1005	                const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
1006	                const int64_t ecnt = base + (cta < rem ? 1 : 0);
1007	                float tsum = 0.0f;
1008	                for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
1009	                    const float gv = grad[e0 + i];
1010	                    tsum += gv * gv;
1011	                }
1012	                float* red = sm.red;
1013	                red[threadIdx.x] = tsum;
1014	                __syncthreads();
1015	                for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
1016	                    if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
1017	                    __syncthreads();
1018	                }
1019	                if (threadIdx.x == 0) sq_part[cta] = red[0];
1020	                bar.sync();   // B2.4a: all per-CTA Σg² partials complete
1021	                if (cta == 0 && threadIdx.x == 0) {
1022	                    double ss = 0.0;
1023	                    for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
1024	                    const float gnorm = sqrtf((float)ss);
1025	                    // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
1026	                    // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
1027	                    *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
1028	                }
1029	                bar.sync();   // B2.4b: rho_over_norm broadcast ready
1030	            }
1031	            const float rho_over_norm = *ron_bc;
1032	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
1033	            //     over the flat param vector (each element owned once → no race).
1034	            {
1035	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
1036	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
1037	                     i < total; i += gstride) {
1038	                    sam_backup[i] = params[i];
1039	                    params[i] = params[i] + rho_over_norm * grad[i];

1390	        stt.exp_avg_sq  = st.exp_avg_sq;
1391	        stt.mu          = const_cast<float*>(st.mu);
1392	        stt.slow        = st.sg2_slow;
1393	        stt.gru_state   = st.sg2_gru_state;
1394	        stt.perm        = nullptr;          // built in-kernel (BuildSort=true)
1395	        stt.unsort      = nullptr;
1396	        stt.workspace   = sg2_meta_ws;
1397	        stt.ws_stride   = sg2_ws_stride<DecSG2Dims>((int64_t)kDecSG2Nmax);
1398	        stt.n_tensors   = kDecNumTensors;
1399	        stt.n           = kDecSizes;        // __constant__ int[]
1400	        stt.row_off     = row_off64;
1401	        __shared__ int task_slot2;
1402	        TaskQueue q2 = ctx.queue();
1403	        for (int t = q2.next_block(&task_slot2); t < kDecNumTensors;
1404	             t = q2.next_block(&task_slot2)) {
1405	            sg2_meta_stages<DecSG2Dims, SG2Weights, float, float, /*BuildSort=*/true>(
1406	                w2, t, stt, sc2, params, grad, st.sharpness, sg2_meta_ws);
1407	        }
1408	        return;   // SG2 owns the whole optimizer phase; skip P3.
1409	    }
1410	
1411	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
1412	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
1413	    st.lr = lr;
1414	#ifdef SG_DEC_PROFILE
1415	    unsigned long long _p3a = (threadIdx.x == 0) ? clock64() : 0;
1416	#endif
1417	    {
1418	        __shared__ int task_slot;
1419	        TaskQueue q = ctx.queue();
1420	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
1421	             t = q.next_block(&task_slot)) {
1422	            const int n = kDecSizes[t];
1423	            const int64_t off = (int64_t)kDecOffsets[t];
1424	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
1425	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
1426	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
1427	            if constexpr (Opt == OptId::Muon) {
1428	                if (dectc::dec_is_muon_2d(t)) continue;
1429	            }
1430	            FusedOptState ts = rebase_state<Opt>(st, off);
1431	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
1432	            //     t == the tensor's flat named_parameters() layer index (the
1433	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
1434	            //     enumeration order, so t IS the eager layer index). bc1 must be
1435	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
1436	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
1437	            if constexpr (Opt == OptId::GrokAdamW) {
1438	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
1439	                ts.beta1 = b1;
