1516	    int dev = 0;
1517	    cudaError_t err = cudaGetDevice(&dev);
1518	    if (err != cudaSuccess) return err;
1519	    int n_sms = 0;

1511	template <OptId Opt>
1512	cudaError_t launch_fused_decoder_megakernel_tc(
1513	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
1514	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1515	        int ncta_cap = 0) {
1516	    int dev = 0;
1517	    cudaError_t err = cudaGetDevice(&dev);
1518	    if (err != cudaSuccess) return err;
1519	    int n_sms = 0;
1520	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1521	    if (err != cudaSuccess) return err;
1522	
1523	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem.
1524	    // DEFAULT (static DecTcSmem): 0 dynamic bytes — unchanged. DEEP RING
1525	    // (SG_DEC_TC_DYNAMIC_SMEM): DecTcSmem lives in DYNAMIC smem, so certify against
1526	    // its real sizeof — and opt the func in to >48 KB dynamic smem FIRST (the cap
1527	    // the occupancy query and the launch both honor). If the deeper ring can't
1528	    // place one block/SM at its real footprint, REFUSE here (the grid barrier
1529	    // requires ≥1 CTA/SM — proceeding would hang); that is the honest "won't
1530	    // launch" signal, surfaced as cudaErrorLaunchOutOfResources, not silenced.
1531	#if SG_DEC_TC_DYNAMIC_SMEM
1532	    const int dyn_smem = (int)sizeof(DecTcSmem);
1533	    err = cudaFuncSetAttribute(
1534	        (const void*)&fused_decoder_megakernel_tc<Opt>,
1535	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
1536	    if (err != cudaSuccess) return err;
1537	#else
1538	    const int dyn_smem = 0;   // static DecTcSmem — byte-identical to the shipped cert
1539	#endif
1540	    int occ = 0;
1541	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1542	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
1543	        /*dynamicSMemBytes=*/dyn_smem);
1544	    if (err != cudaSuccess) return err;
1545	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1546	
1547	    unsigned launch_ctas = (unsigned)n_sms;
1548	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1549	    ctx.n_ctas = launch_ctas;
1550	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
1551	    // AND it guarantees full token tiles for the projections). NO G-divisibility
1552	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
1553	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
1554	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
1555	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
